INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `image`, `category`, `status`, `views`, `published_at`, `created_at`, `updated_at`) VALUES (11, 'Dies Natalis ke-8 STIKes Panti Waluya Malang: Bound by Vision, Boosted by Innovation, Beyond Infinity', 'dies-natalis-ke-8-stikes-panti-waluya-malang-bound-by-vision-boosted-by-innovation-beyond-infinity-1789621666', NULL, '<h2>Dies Natalis ke-8 STIKes Panti Waluya Malang: Bound by Vision, Boosted by Innovation, Beyond Infinity</h2><p><strong>Malang, 21–24 Agustus 2026</strong> — Dalam semangat kebersamaan dan rasa syukur atas perjalanan delapan tahun berkarya di dunia pendidikan kesehatan, STIKes Panti Waluya Malang menyelenggarakan rangkaian kegiatan <strong>Dies Natalis ke-8</strong> dengan mengusung tema <strong>"Bound by Vision, Boosted by Innovation, Beyond Infinity."</strong></p><p>Tema ini menjadi refleksi komitmen STIKes Panti Waluya Malang untuk terus melangkah bersama dalam satu visi, mendorong inovasi di setiap bidang, serta menghadirkan kontribusi yang berkelanjutan bagi masyarakat tanpa batas.</p><p>Selama empat hari penyelenggaraan, mulai <strong>21 hingga 24 Agustus 2026</strong>, berbagai kegiatan akademik, olahraga, seni, budaya, dan pengabdian kepada masyarakat akan menjadi bagian dari perayaan Dies Natalis. Setiap kegiatan dirancang untuk mempererat kebersamaan seluruh sivitas akademika sekaligus memperkuat nilai-nilai pelayanan, kreativitas, dan kepedulian sosial.</p><p>Rangkaian kegiatan diawali dengan <strong>Lomba Badminton</strong>, yang menjadi ajang mempererat sportivitas, kekompakan, dan semangat kompetisi sehat antar sivitas akademika. Selain menjaga kebugaran, kegiatan ini juga menjadi wadah membangun kebersamaan di luar lingkungan akademik.</p><p>Semangat pengembangan ilmu pengetahuan diwujudkan melalui <strong>Kuliah Tamu</strong> yang menghadirkan narasumber inspiratif dari bidang kesehatan dan profesional terkait. Kegiatan ini diharapkan mampu memperluas wawasan, mendorong pemikiran kritis, serta memotivasi mahasiswa untuk terus berkembang menghadapi tantangan dunia kesehatan yang semakin dinamis.</p><p>Nuansa kebersamaan semakin terasa melalui <strong>Lomba Menghias Tumpeng</strong>, sebuah kegiatan yang tidak hanya menampilkan kreativitas dalam seni penyajian, tetapi juga melestarikan budaya Indonesia serta memperkuat kerja sama antar tim.</p><p>Keberagaman budaya Indonesia turut ditampilkan dalam <strong>Gelar Budaya</strong>, yang menjadi ruang ekspresi bagi mahasiswa untuk menampilkan berbagai pertunjukan seni dan budaya dari berbagai daerah. Melalui kegiatan ini, STIKes Panti Waluya Malang ingin menumbuhkan rasa bangga terhadap warisan budaya sekaligus mempererat persaudaraan dalam keberagaman.</p><p>Sebagai institusi yang menjunjung tinggi nilai kemanusiaan, rangkaian Dies Natalis juga diisi dengan <strong>Kunjungan dan Bakti Sosial ke Panti Jompo</strong>. Kegiatan ini menjadi bentuk nyata kepedulian sosial melalui pelayanan, kebersamaan, serta berbagi kasih kepada para lanjut usia sebagai wujud implementasi nilai-nilai pengabdian kepada masyarakat.</p><p>Kemeriahan perayaan semakin lengkap dengan hadirnya <strong>Bazaar</strong>, yang menghadirkan berbagai stan makanan, minuman, produk kreatif, serta usaha dari mahasiswa maupun mitra. Bazaar menjadi ruang interaksi yang memperkuat kebersamaan sekaligus mendukung semangat kewirausahaan di lingkungan kampus.</p><p>Melalui rangkaian kegiatan Dies Natalis ke-8 ini, STIKes Panti Waluya Malang berharap seluruh sivitas akademika dapat terus memperkuat sinergi, meningkatkan semangat berinovasi, dan memberikan kontribusi nyata bagi dunia pendidikan, pelayanan kesehatan, serta masyarakat luas.</p><p>Mari bersama merayakan perjalanan delapan tahun penuh dedikasi dan prestasi, melangkah menuju masa depan yang lebih gemilang dengan semangat <strong>"Bound by Vision, Boosted by Innovation, Beyond Infinity."</strong></p>', '/storage/posts/POJRtJIDR1z6ngiHcnJxyZrfQjbWed0S9NhFlEAP.jpg', 'Kegiatan Mahasiswa', 'published', 2, '2026-09-17 05:07:46', '2026-09-17 05:07:46', '2026-09-17 05:08:23');
